/**
 * The dummy frame for "What is this?".
 *
 * The brief for this build is: "send a dummy image to the api and tell it to
 * describe". That makes this screen work with no camera at all, which matters
 * because the iOS Simulator has no camera and expo-camera is device-only.
 *
 * The image is a synthetic Hong Kong pavement scene — tactile paving, a step
 * edge, a handrail — generated by scripts/make-demo-frame.mjs. It is deliberately
 * a scene with recognisable content rather than a grey square, so the vision
 * response is meaningful to look at and to listen to.
 *
 * It is sent as base64 inside JSON, so the bytes are opaque to the API and only
 * the declared MIME type has to be true. The asset is a real PNG, so image/png.
 *
 * NOTE on asset resolution: React Native 0.86 does NOT expose
 * `Image.resolveAssetSource` (the file in Libraries/Image is internal and not
 * re-exported). `expo-asset`'s `Asset.loadAsync` is the supported way to turn a
 * `require()` into a readable local file uri on iOS and Android.
 */

import { Asset } from 'expo-asset';
import { File } from 'expo-file-system';

/** Metro turns this into an asset reference; resolved to a file at call time. */
export const DEMO_FRAME = require('../../assets/demo/sidewalk.png');

export const DEMO_FRAME_MIME = 'image/png';

function toBase64FromBytes(buffer) {
  const bytes = new Uint8Array(buffer);
  let binary = '';
  // Chunked: String.fromCharCode.apply blows the argument limit on larger images.
  const chunk = 0x8000;
  for (let i = 0; i < bytes.length; i += chunk) {
    binary += String.fromCharCode.apply(null, bytes.subarray(i, i + chunk));
  }
  return btoa(binary);
}

/**
 * Resolve the bundled asset to a local file uri.
 *
 * `loadAsync` guarantees the bytes are on disk, so `localUri` is populated. The
 * remote `uri` is only reachable while a dev server is running, so it is a last
 * resort rather than the normal path.
 */
async function resolveLocalUri() {
  const [asset] = await Asset.loadAsync(DEMO_FRAME);
  const uri = asset?.localUri ?? asset?.uri;
  if (!uri) throw new Error('The demo image could not be resolved to a local file.');
  return uri;
}

/**
 * Read the bundled demo frame as raw base64 (no data: prefix).
 * @returns {Promise<{ base64: string, dataUri: string, source: string }>}
 */
export async function loadDemoFrame() {
  const uri = await resolveLocalUri();
  const file = new File(uri);

  const exists = file.exists ?? true;
  if (!exists) throw new Error('The demo image is missing from the bundle.');

  const size = typeof file.size === 'number' ? file.size : null;
  if (size === 0) throw new Error('The demo image is empty.');

  // base64() is the direct path; the byte fallback keeps this working if the
  // native method is unavailable in some runtime.
  let base64;
  try {
    base64 = await file.base64();
  } catch {
    base64 = toBase64FromBytes(await file.arrayBuffer());
  }

  if (!base64) throw new Error('The demo image produced no data.');

  return {
    base64,
    dataUri: `data:${DEMO_FRAME_MIME};base64,${base64}`,
    source: uri,
  };
}
